import { createClient } from "@connectrpc/connect";
import { useTransport } from "@connectrpc/connect-query";
import { KeyIcon } from "@heroicons/react/24/outline";
import { useQueryClient } from "@tanstack/react-query";
import { AuthService } from "gen/auth/v1/auth_pb";
import { UserService } from "gen/users/v1/users_pb";
import {
  errorMessage,
  isCancelled,
  passkeysSupported,
  signInWithPasskey,
} from "helpers/passkeys";
import { invalidateServices } from "helpers/query";
import React, { useMemo, useState } from "react";

// SignInForm signs in with a passkey.
const SignInForm: React.FC = () => {
  const queryClient = useQueryClient();
  const transport = useTransport();
  const client = useMemo(
    () => createClient(AuthService, transport),
    [transport]
  );
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");

  const signIn = () => {
    setPending(true);
    setError("");
    signInWithPasskey(client)
      .then(async () => {
        await invalidateServices(queryClient, [UserService]);
      })
      .catch((error_: unknown) => {
        if (
          error_ instanceof DOMException &&
          error_.name === "NotAllowedError"
        ) {
          /**
           * Browsers report a cancelled prompt and a passkey that couldn't
           * be used alike, so say both.
           */
          setError(
            "Signing in didn't finish: it was cancelled, or this device has no passkey for mealplann.ing. Try again, or use a device with your passkey."
          );
        } else if (!isCancelled(error_)) {
          setError(errorMessage(error_));
        }
      })
      .finally(() => {
        setPending(false);
      });
  };

  return (
    <div className="flex w-full max-w-sm flex-col gap-4">
      <div className="flex flex-col gap-1">
        <h2 className="text-2xl font-bold text-ink">Sign in</h2>
        <p className="text-sm text-stone-600">
          Use the passkey saved on this device.
        </p>
      </div>
      {passkeysSupported() ? (
        <button
          type="button"
          disabled={pending}
          className="inline-flex items-center justify-center gap-2 rounded-lg bg-ink px-4 py-3 text-[15px] font-semibold text-neutral-50 hover:bg-neutral-800 focus:outline-hidden focus-visible:ring-2 focus-visible:ring-leaf focus-visible:ring-offset-2 disabled:opacity-50"
          onClick={signIn}
        >
          <KeyIcon className="size-[18px] text-leaf" />
          {pending ? "Waiting for passkey…" : "Sign in with a passkey"}
        </button>
      ) : (
        <p className="text-sm text-stone-600">
          This browser doesn&apos;t support passkeys.
        </p>
      )}
      {error !== "" && <p className="text-[13px] text-brand-700">{error}</p>}
      <p className="border-t border-stone-200 pt-3 text-[13px] leading-normal text-stone-500">
        mealplann.ing is invite only. To create an account, ask for an
        invitation link.
      </p>
    </div>
  );
};

export default SignInForm;
